const n={paperItems:["Buổi tối trước khi ngủ hoặc lúc cần tách khỏi màn hình điện thoại để viết chậm bằng tay.","Khi muốn vẽ phác, ghi chú tự do ngoài lề hoặc lưu giữ trang viết dài cho riêng mình.","Lúc cần ngồi yên tĩnh 10–15 phút để hoàn thành trọn vẹn một trang bài tập CBT."],webItems:["Giữa giờ học hoặc lúc đang ở trường cần check-in nhanh cảm xúc chỉ trong 30 giây.","Khi muốn xem lại hướng dẫn từng bước hoặc tra tên 10 kiểu suy nghĩ thường gặp.","Lúc muốn đặt câu hỏi ẩn danh hoặc xem quy trình đặt lịch tham vấn (bản demo)."],rhythmSteps:[{title:"1. Dừng lại và check-in nhanh",detail:"Mở web để gọi tên cảm xúc và mức độ hiện tại bất cứ lúc nào trong ngày."},{title:"2. Chọn viết trên giấy hoặc trên web",detail:"Nếu đang tiện cầm sổ tay Họa, bạn mở đúng trang bài tập tương ứng; nếu đang di chuyển, bạn viết nháp ngay trên web."},{title:"3. Nhìn lại nhẹ nhàng",detail:"Cuối tuần mở Nhật ký hoặc lật lại sổ giấy để nhận ra điều gì giúp bạn thấy vững hơn, không chấm điểm hay tự trách."}]},t={paperItems:["In the evening before sleep, or whenever you want a break from screens to write slowly by hand.","When you want to sketch, jot margin notes freely, or keep longer personal reflections offline.","When you have 10–15 quiet minutes to sit with a full CBT worksheet page."],webItems:["Between classes on campus when you want a quick 30-second mood check-in.","When you need step-by-step prompts or want to look up the 10 common thinking patterns.","When you want to try anonymous Q&A or preview booking a counseling slot (demo)."],rhythmSteps:[{title:"1. Pause for a quick check-in",detail:"Open the web companion anytime during the day to name what you feel and how intense it is."},{title:"2. Write on paper or online",detail:"If your Họa notebook is nearby, turn to the suggested exercise page; if you are out, draft directly on the web."},{title:"3. Reflect gently",detail:"Browse your Journal or flip back through your notebook at your own pace, without scores or streaks."}]};expor